static int
tsk_treeseq_pair_coalescence_non_missing_span(const tsk_treeseq_t *self,
    tsk_size_t num_windows, const double *windows, double *non_missing_span)
{
    int ret = 0;
    tsk_tree_position_t tree_pos;
    tsk_id_t u;
    tsk_size_t active_edges = 0;
    tsk_size_t w = 0;
    double left, right, a, b;

